 * Permanently deletes an issue with its label links, comments and
 * attachments. The issue's number is retired in the project's watermark
 * first, so it is never handed out again.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<PurgedIssue | null> {
  return getDb().transaction((tx) => {
    const row = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
