  await expect(issueService.restoreIssue(t.actors.member, t.org.id, a.id)).rejects.toMatchObject({ reason: "not_archived" });
  expect(toAppError(new RestoreRefusedError("Issue", "x", "quota")).code).toBe("conflict");
  await issueService.archiveIssue(t.actors.member, t.org.id, a.id);
  expect((await usageRepo.getUsage(t.org.id)).issuesUsed).toBe(1);
  const r = await issueService.restoreIssue(t.actors.member, t.org.id, a.id);
  expect(r.archivedAt).toBeNull(); expect(r.number).toBe(1);
  expect((await usageRepo.getUsage(t.org.id)).issuesUsed).toBe(2);
  expect((await searchRepo.countIndexed(t.org.id))).toBeGreaterThan(0);

